-- Phase 13 store reviews moderation foundation
create table if not exists public.fr_store_reviews (id uuid primary key default gen_random_uuid(),customer_id uuid not null references public.profiles(id) on delete cascade,partner_id uuid not null references public.profiles(id) on delete cascade,rating smallint not null check(rating between 1 and 5),review_text text check(review_text is null or length(review_text)<=1200),status text not null default 'pending' check(status in ('pending','approved','rejected')),purchase_verified boolean not null default false,admin_note text,reviewed_by uuid references public.profiles(id),reviewed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(customer_id,partner_id),check(customer_id<>partner_id));
alter table public.fr_store_reviews enable row level security;
drop policy if exists fr_store_reviews_public_approved_read on public.fr_store_reviews;
create policy fr_store_reviews_public_approved_read on public.fr_store_reviews for select to anon,authenticated using(status='approved');
drop policy if exists fr_store_reviews_owner_read on public.fr_store_reviews;
create policy fr_store_reviews_owner_read on public.fr_store_reviews for select to authenticated using(customer_id=auth.uid() or public.is_friend_ride_admin());
drop policy if exists fr_store_reviews_customer_insert on public.fr_store_reviews;
create policy fr_store_reviews_customer_insert on public.fr_store_reviews for insert to authenticated with check(customer_id=auth.uid() and status='pending' and purchase_verified=false and reviewed_by is null and reviewed_at is null and exists(select 1 from public.profiles p where p.id=auth.uid() and lower(p.role)='customer') and exists(select 1 from public.profiles p where p.id=partner_id and lower(p.role) in ('partner','shop_partner','store_partner')));
drop policy if exists fr_store_reviews_customer_update on public.fr_store_reviews;
create policy fr_store_reviews_customer_update on public.fr_store_reviews for update to authenticated using(customer_id=auth.uid() and status='pending') with check(customer_id=auth.uid() and status='pending' and purchase_verified=false and reviewed_by is null and reviewed_at is null);
drop policy if exists fr_store_reviews_admin_all on public.fr_store_reviews;
create policy fr_store_reviews_admin_all on public.fr_store_reviews for all to authenticated using(public.is_friend_ride_admin()) with check(public.is_friend_ride_admin());
create or replace function public.fr_store_review_admin_moderate(p_review_id uuid,p_decision text,p_note text default null) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_uid uuid:=auth.uid();v_row public.fr_store_reviews%rowtype;begin if v_uid is null then raise exception 'Authentication required';end if;if not public.is_friend_ride_admin() then raise exception 'Admin only';end if;if p_decision not in ('approve','reject') then raise exception 'Invalid decision';end if;select * into v_row from public.fr_store_reviews where id=p_review_id for update;if not found then return jsonb_build_object('ok',false,'reason','not_found');end if;if v_row.status<>'pending' then return jsonb_build_object('ok',false,'reason','already_reviewed');end if;update public.fr_store_reviews set status=case when p_decision='approve' then 'approved' else 'rejected' end,admin_note=p_note,reviewed_by=v_uid,reviewed_at=now(),updated_at=now() where id=p_review_id;return jsonb_build_object('ok',true,'decision',p_decision,'purchase_verified',false);end;$$;
revoke all on function public.fr_store_review_admin_moderate(uuid,text,text) from public,anon;
grant execute on function public.fr_store_review_admin_moderate(uuid,text,text) to authenticated;